const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // PG* env vars
const router = express.Router();

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString('base64url');

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let after = [];
  if (req.query.cursor) {
    try {
      after = JSON.parse(Buffer.from(String(req.query.cursor), 'base64url').toString());
    } catch {
      after = null;
    }
    if (!Array.isArray(after) || after.length !== 2 || !after.every((v) => typeof v === 'string')) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
  }

  try {
    // Fetch one extra row to know whether another page exists.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
        ${after.length ? 'WHERE (created_at, id) < ($2, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...after]
    );
    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Class 22 = data exception: well-formed cursor carrying a bad timestamp/id.
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
